// Applies the SQL migrations in apps/server/drizzle/ (generated by `db:generate`) in order. Used by
// `pnpm db:migrate` (src/db/migrate.ts, dist/migrate.js) and, with MIGRATE_ON_START=true, by the
// server itself at startup (hosts without a pre-deploy step, such as Render's free plan).
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { migrate } from 'drizzle-orm/postgres-js/migrator';
import { createDb } from './client';

/** The drizzle/ folder: src/db/*.ts (tsx) and dist/*.js (bundled) sit at different depths. */
export function findMigrationsFolder(fromDir: string = path.dirname(fileURLToPath(import.meta.url))): string {
  const found = [path.resolve(fromDir, '..', '..', 'drizzle'), path.resolve(fromDir, '..', 'drizzle')].find(d => fs.existsSync(path.join(d, 'meta')));
  if (!found) throw new Error('drizzle/ migrations folder not found');
  return found;
}

/** Runs every pending migration on its own one-connection pool; returns the folder used. */
export async function runMigrations(databaseUrl: string): Promise<string> {
  const migrationsFolder = findMigrationsFolder();
  const { db, close } = createDb(databaseUrl, { max: 1 });
  try {
    await migrate(db, { migrationsFolder });
    return migrationsFolder;
  } finally {
    await close();
  }
}
